command -v node && node -e '
const lines=require("fs").readFileSync("/tmp/<path>","utf8").split("\n");
const prog=lines.map(l=>l.split(";")[0].trim()).filter(l=>l.length).map(l=>l.split(/\s+/));
const R={a:0,b:0,c:0,d:0};
const val=x=>Object.prototype.hasOwnProperty.call(R,x)?R[x]:Number(x);
const mod=v=>((v%65536)+65536)%65536;
let ip=0,sum=0,n=0,outs=0;
while(ip>=0&&ip<prog.length){
  const p=prog[ip];n++;const op=p[0];
  if(op==="set"){R[p[1]]=mod(val(p[2]));ip++;}
  else if(op==="add"){R[p[1]]=mod(R[p[1]]+val(p[2]));ip++;}
  else if(op==="mul"){R[p[1]]=mod(R[p[1]]*val(p[2]));ip++;}
  else if(op==="mod"){const x=val(p[2]);if(x>0)R[p[1]]=R[p[1]]%x;ip++;}
  else if(op==="dec"){R[p[1]]=Math.max(0,R[p[1]]-1);ip++;}
  else if(op==="jnz"){ip+=val(p[1])!==0?val(p[2]):1;}
  else if(op==="skp"){ip+=val(p[1])<val(p[2])?2:1;}
  else if(op==="out"){sum+=val(p[1]);outs++;ip++;}
}
console.log("sum",sum,"count",n,"outs",outs,"regs",R);
'

